<script setup lang="ts">
import { computed,ref } from 'vue'
import Icon from './Icon.vue'
import type { PersonalState,PersonalCap } from './types'
const props=defineProps<{personal?:PersonalState;mode:string;caps:PersonalCap;name:string}>()
const hover=ref<Record<string,number>>({primary:-1,secondary:-1})
const format=(n:number)=>Intl.NumberFormat('zh-CN',{notation:n>99999?'compact':'standard',maximumFractionDigits:1}).format(n)
const charts=computed(()=>['primary','secondary'].map((key,index)=>{
 const data=props.personal?.plans[props.mode]?.[key] || {total:0,points:[],seconds:index?604800:18000}
 const now=props.personal?.updated || Date.now()/1000,start=now-data.seconds
 const ceiling=Math.max(data.total*1.15,props.caps.enabled?props.caps[key as 'primary'|'secondary']:0,1)
 let cumulative=0
 const points=data.points.map(p=>{cumulative+=p.tokens;return {...p,total:cumulative,x:42+Math.max(0,Math.min(1,(p.at-start)/data.seconds))*460,y:145-cumulative/ceiling*120}})
 return {key,title:index?'近 7 天':'近 5 小时',data,points,ceiling,path:points.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' '),capY:145-props.caps[key as 'primary'|'secondary']/ceiling*120}
}))
function pointer(key:string,event:PointerEvent){const svg=event.currentTarget as SVGElement;const bounds=svg.getBoundingClientRect();const x=(event.clientX-bounds.left)/bounds.width*520;const chart=charts.value.find(c=>c.key===key)!;let nearest=-1,distance=Infinity;chart.points.forEach((p,i)=>{if(Math.abs(p.x-x)<distance){nearest=i;distance=Math.abs(p.x-x)}});hover.value[key]=nearest}
</script>
<template><div class="personal-chart-grid"><article v-for="chart in charts" :key="chart.key" class="panel personal-chart"><div class="metric-top"><span><Icon name="pulse" :size="15"/>{{ chart.title }} · {{ mode.toUpperCase() }}</span><span class="badge subtle">{{ name }}</span></div><div class="personal-total"><strong>{{ format(chart.data.total) }}</strong><span>已记录 tokens</span><span v-if="caps.enabled" class="chart-budget">上限 {{ format(caps[chart.key as 'primary'|'secondary']) }}</span></div><div v-if="!chart.points.length" class="chart-empty"><Icon name="pulse" :size="25"/><span>暂无个人用量样本</span><small>只接收归属对话事件或手动导入的记录，不使用账号消耗推算。</small></div><div v-else class="chart-plot"><svg viewBox="0 0 520 178" role="img" :aria-label="`${name}${chart.title}累计记录${chart.data.total} tokens`" @pointermove="pointer(chart.key,$event)" @pointerleave="hover[chart.key]=-1"><defs><linearGradient :id="`usage-fill-${chart.key}`" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".16"/><stop offset="100%" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><g class="chart-grid-lines"><path d="M42 25H502M42 85H502M42 145H502"/><text x="0" y="29">{{ format(chart.ceiling) }}</text><text x="0" y="89">{{ format(chart.ceiling/2) }}</text><text x="20" y="149">0</text><text x="42" y="170">{{ chart.title }}前</text><text x="476" y="170">现在</text></g><path v-if="chart.points.length>1" :d="`${chart.path}L${chart.points.at(-1)!.x},145L${chart.points[0].x},145Z`" :fill="`url(#usage-fill-${chart.key})`"/><path v-if="caps.enabled" :d="`M42 ${chart.capY}H502`" class="chart-cap"/><path :d="chart.path" class="usage-flow-path"/><circle v-for="(point,i) in chart.points" v-show="i===chart.points.length-1 || i===hover[chart.key]" :key="point.at" :cx="point.x" :cy="point.y" :r="i===hover[chart.key]?4:3" class="usage-dot"/><g v-if="chart.points[hover[chart.key]]"><path :d="`M${chart.points[hover[chart.key]].x} 22V145`" class="chart-crosshair"/></g></svg><div v-if="chart.points[hover[chart.key]]" class="chart-tooltip">{{ new Date(chart.points[hover[chart.key]].at*1000).toLocaleString('zh-CN',{hour12:false}) }}<strong>本段 +{{ format(chart.points[hover[chart.key]].tokens) }} · 累计 {{ format(chart.points[hover[chart.key]].total) }} tokens</strong></div></div><div class="chart-caption"><span class="status-dot"></span>分钟聚合 · 仅包含明确归属的用量</div></article></div></template>
